package org.springframework.batch.core.job.parameters;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

/**
 * Value object representing runtime parameters to a batch job. Because the parameters
 * have no individual meaning outside of the {@code JobParameters} object they are
 * contained within, it is a value object rather than an entity. It is also extremely
 * important that a parameters object can be reliably compared to another for equality, in
 * order to determine if one {@code JobParameters} object equals another. Furthermore,
 * because these parameters need to be persisted, it is vital that the types added are
 * restricted.
 * <p>
 * This class is immutable and, therefore, thread-safe.
 *
 * @author Lucas Ward
 * @author Michael Minella
 * @author Mahmoud Ben Hassine
 * @author Taeik Lim
 * @since 1.0
 */
public class JobParameters implements Serializable {

	private final JobParametersStore parameterStore;

	private final JobParametersTypedAccessors typedAccessors;

	/**
	 * Default constructor.
	 */
	public JobParameters() {
		this.parameterStore = new JobParametersStore();
		this.typedAccessors = new JobParametersTypedAccessors(this.parameterStore.getParameters());
	}

	/**
	 * Constructor that is initialized with the content of a {@link Map} that contains a
	 * {@code String} key and a {@link JobParameter} value.
	 * @param parameters The {@link Map} that contains a {@code String} key and a
	 * {@link JobParameter} value.
	 */
	public JobParameters(Map<String, JobParameter<?>> parameters) {
		this.parameterStore = new JobParametersStore(parameters);
		this.typedAccessors = new JobParametersTypedAccessors(this.parameterStore.getParameters());
	}

	public Long getLong(String key) {
		return this.typedAccessors.getLong(key);
	}

	public Long getLong(String key, Long defaultValue) {
		return this.typedAccessors.getLong(key, defaultValue);
	}

	public String getString(String key) {
		return this.typedAccessors.getString(key);
	}

	public String getString(String key, String defaultValue) {
		return this.typedAccessors.getString(key, defaultValue);
	}

	public Double getDouble(String key) {
		return this.typedAccessors.getDouble(key);
	}

	public Double getDouble(String key, Double defaultValue) {
		return this.typedAccessors.getDouble(key, defaultValue);
	}

	public java.util.Date getDate(String key) {
		return this.typedAccessors.getDate(key);
	}

	public java.util.Date getDate(String key, java.util.Date defaultValue) {
		return this.typedAccessors.getDate(key, defaultValue);
	}

	public java.time.LocalDate getLocalDate(String key) {
		return this.typedAccessors.getLocalDate(key);
	}

	public java.time.LocalDate getLocalDate(String key, java.time.LocalDate defaultValue) {
		return this.typedAccessors.getLocalDate(key, defaultValue);
	}

	public java.time.LocalTime getLocalTime(String key) {
		return this.typedAccessors.getLocalTime(key);
	}

	public java.time.LocalTime getLocalTime(String key, java.time.LocalTime defaultValue) {
		return this.typedAccessors.getLocalTime(key, defaultValue);
	}

	public java.time.LocalDateTime getLocalDateTime(String key) {
		return this.typedAccessors.getLocalDateTime(key);
	}

	public java.time.LocalDateTime getLocalDateTime(String key, java.time.LocalDateTime defaultValue) {
		return this.typedAccessors.getLocalDateTime(key, defaultValue);
	}

	public JobParameter<?> getParameter(String key) {
		return this.parameterStore.getParameter(key);
	}

	/**
	 * Get a map of all parameters.
	 * @return an unmodifiable map containing all parameters.
	 */
	public Map<String, JobParameter<?>> getParameters() {
		return this.parameterStore.getParameters();
	}

	/**
	 * Get a map of identifying parameters.
	 * @since 5.1
	 * @return an unmodifiable map containing identifying parameters.
	 */
	public Map<String, JobParameter<?>> getIdentifyingParameters() {
		return this.parameterStore.getIdentifyingParameters();
	}

	/**
	 * @return {@code true} if the parameters object is empty or {@code false} otherwise.
	 */
	public boolean isEmpty() {
		return this.parameterStore.isEmpty();
	}

	@Override
	public boolean equals(Object obj) {
		if (!(obj instanceof JobParameters rhs)) {
			return false;
		}

		if (obj == this) {
			return true;
		}

		return this.getParameters().equals(rhs.getParameters());
	}

	@Override
	public int hashCode() {
		return 17 + 23 * this.getParameters().hashCode();
	}

	@Override
	public String toString() {
		List<String> parameters = new ArrayList<>();
		for (Map.Entry<String, JobParameter<?>> entry : this.getParameters().entrySet()) {
			parameters.add(String.format("'%s':'%s'", entry.getKey(), entry.getValue()));
		}
		return "{" + String.join(",", parameters) + "}";
	}

}

