package org.springframework.batch.core.job.parameters;

import java.io.Serializable;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;

import org.springframework.util.Assert;

final class JobParametersStore implements Serializable {

	private final Map<String, JobParameter<?>> parameters;

	JobParametersStore() {
		this.parameters = new HashMap<>();
	}

	JobParametersStore(Map<String, JobParameter<?>> parameters) {
		this.parameters = new HashMap<>(parameters);
	}

	JobParameter<?> getParameter(String key) {
		Assert.notNull(key, "key must not be null");
		return this.parameters.get(key);
	}

	Map<String, JobParameter<?>> getParameters() {
		return Collections.unmodifiableMap(this.parameters);
	}

	Map<String, JobParameter<?>> getIdentifyingParameters() {
		Map<String, JobParameter<?>> identifyingParameters = new HashMap<>();
		for (Map.Entry<String, JobParameter<?>> entry : this.parameters.entrySet()) {
			if (entry.getValue().isIdentifying()) {
				identifyingParameters.put(entry.getKey(), entry.getValue());
			}
		}
		return Collections.unmodifiableMap(identifyingParameters);
	}

	boolean isEmpty() {
		return this.parameters.isEmpty();
	}

}

