	}

	@Override
	public void afterPropertiesSet() throws Exception {
		Assert.state(StringUtils.hasText(this.namedQuery), "Named query cannot be empty");
		Assert.state(this.entityClass != null, "Entity class cannot be NULL");
	}

}

