package org.springframework.batch.item.file.transform;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

import org.springframework.util.Assert;

/**
 * Line-tokenizer using a regular expression to filter out data (by using matching and
 * non-matching groups). Consider the following regex which picks only the first and last
 * name (notice the non-matching group in the middle): <pre>
 * (.*?)(?: .*)* (.*)
 * </pre> For the names:
 * <ul>
 * <li>"Graham James Edward Miller"</li>
 * <li>"Andrew Gregory Macintyre"</li>
 * <li>"No MiddleName"</li>
 * </ul>
 *
 * the output will be:
 * <ul>
 * <li>"Miller", "Graham"</li>
 * <li>"Macintyre", "Andrew"</li>
 * <li>"MiddleName", "No"</li>
 * </ul>
 *
 * An empty list is returned, in case of a non-match.
 *
 * @see Matcher#group(int)
 * @author Costin Leau
 * @author Stefano Cordio
 */
public class RegexLineTokenizer extends AbstractLineTokenizer {

	private Pattern pattern;

	/**
	 * Create a new {@link RegexLineTokenizer} with the provided regex.
	 * @param regex regular expression (as a String)
	 * @since 6.0
	 */
	public RegexLineTokenizer(String regex) {
		Assert.hasText(regex, "a valid regex is required");
		this.pattern = Pattern.compile(regex);
	}

	@Override
	protected List<String> doTokenize(String line) {
		Matcher matcher = pattern.matcher(line);
		boolean matchFound = matcher.find();

		if (matchFound) {
			List<String> tokens = new ArrayList<>(matcher.groupCount());
			for (int i = 1; i <= matcher.groupCount(); i++) {
				tokens.add(matcher.group(i));
			}
			return tokens;
		}
		return Collections.emptyList();
	}

	/**
	 * Sets the regex pattern to use.
	 * @param pattern Regular Expression pattern
	 */
	public void setPattern(Pattern pattern) {
		Assert.notNull(pattern, "a non-null pattern is required");
		this.pattern = pattern;
	}

	/**
	 * Sets the regular expression to use.
	 * @param regex regular expression (as a String)
	 */
	public void setRegex(String regex) {
		Assert.hasText(regex, "a valid regex is required");
		this.pattern = Pattern.compile(regex);
	}

}

