package org.springframework.batch.item.jms;

import org.apache.commons.logging.Log;
import org.apache.commons.logging.LogFactory;
import org.jspecify.annotations.Nullable;

import org.springframework.retry.interceptor.MethodInvocationRecoverer;
import org.springframework.jms.JmsException;
import org.springframework.jms.core.JmsOperations;
import org.springframework.util.Assert;

/**
 * @author Dave Syer
 * @author Mahmoud Ben Hassine
 *
 */
public class JmsMethodInvocationRecoverer<T> implements MethodInvocationRecoverer<T> {

	protected Log logger = LogFactory.getLog(getClass());

	private JmsOperations jmsTemplate;

	/**
	 * Create a new {@link JmsMethodInvocationRecoverer} with the provided
	 * {@link JmsOperations}.
	 * @param jmsTemplate a {@link JmsOperations} instance
	 * @since 6.0
	 */
	public JmsMethodInvocationRecoverer(JmsOperations jmsTemplate) {
		Assert.notNull(jmsTemplate, "jmsTemplate must not be null");
		this.jmsTemplate = jmsTemplate;
	}

	/**
	 * Setter for jms template.
	 * @param jmsTemplate a {@link JmsOperations} instance
	 */
	public void setJmsTemplate(JmsOperations jmsTemplate) {
		this.jmsTemplate = jmsTemplate;
	}

	/**
	 * Send one message per item in the argument list using the default destination of the
	 * jms template. If the recovery is successful {@code null} is returned.
	 *
	 * @see MethodInvocationRecoverer#recover(Object[], Throwable)
	 */
	@Override
	public @Nullable T recover(Object[] items, Throwable cause) {
		try {
			for (Object item : items) {
				jmsTemplate.convertAndSend(item);
			}
			return null;
		}
		catch (JmsException e) {
			logger.error("Could not recover because of JmsException.", e);
			throw e;
		}
	}

}

