	}

	@Test
	void testTransactionalRemoveWithRollback() {
		Exception exception = assertThrows(RuntimeException.class,
				() -> transactionTemplate.execute((TransactionCallback<Void>) status -> {
					testRemove();
					throw new RuntimeException("Rollback!");
				}));
